"""**Step 03 - Full Context Baseline**

Stuff the first 50 chunks directly into Claude's context window. Measure token count, latency, and cost per query.
"""

# Build the full-context string from first 50 chunks
CORPUS_SIZE = 50
full_corpus_docs = all_docs[:CORPUS_SIZE]

full_corpus_text = "\n\n---\n\n".join([
    f"[Doc {i+1}: {d.metadata['title']}]\n{d.page_content}"
    for i, d in enumerate(full_corpus_docs)
])

# Estimate tokens without tiktoken (no network needed)
# Approximation: ~0.75 tokens per word (conservative)
word_count    = len(full_corpus_text.split())
corpus_tokens = int(word_count * 1.33)

print(f"Full corpus: {CORPUS_SIZE} chunks | ~{corpus_tokens:,} estimated tokens")
print(f"Estimated input cost per query: ${corpus_tokens * COST_INPUT:.5f}")

@dataclass
class FullCtxResult:
    answer:        str
    generate_ms:   float
    input_tokens:  int = 0
    output_tokens: int = 0

    @property
    def total_ms(self):
        return self.generate_ms

    @property
    def cost_usd(self):
        return self.input_tokens * COST_INPUT + self.output_tokens * COST_OUTPUT


def full_context_answer(query: str) -> FullCtxResult:
    """Stuff entire corpus into HuggingFace context and ask."""
    # HuggingFacePipeline expects a single string input for text-generation.
    # The model will complete the prompt.
    # Estimate token length (simple char count / 4 for approximation)
    # distilgpt2 has a max_length of 1024 tokens.
    MAX_MODEL_INPUT_TOKENS = 1024
    # Reserve some tokens for the question and instructions
    HEADER_FOOTER_TOKENS = 100 # Approximation for 'Answer based on...' and 'Question: ... Answer:'
    MAX_CONTEXT_TOKENS = MAX_MODEL_INPUT_TOKENS - HEADER_FOOTER_TOKENS

    # Truncate full_corpus_text if it's too long
    # Simple char-based truncation as an approximation of token count
    # Assuming ~4 chars per token
    max_context_chars = MAX_CONTEXT_TOKENS * 4
    truncated_full_corpus_text = full_corpus_text
    if len(full_corpus_text) > max_context_chars:
        truncated_full_corpus_text = full_corpus_text[:max_context_chars]
        print(f"Warning: Truncated full_corpus_text from {len(full_corpus_text)} to {len(truncated_full_corpus_text)} characters to fit model's context window.")


    formatted_prompt = (
        "Answer based on the provided documents. Be concise and accurate.\n\n"
        f"Context:\n{truncated_full_corpus_text}\n\n"
        f"Question: {query}\n"
        "Answer:"
    )

    t0 = time.perf_counter()
    # For causal LMs, the model generates text after the prompt. We need to extract only the generated part.
    response = llm.invoke(formatted_prompt)
    # The response from a causal LM with text-generation task will include the prompt itself.
    # We extract the part of the response that comes *after* the formatted prompt.
    generated_text = response[len(formatted_prompt):].strip()
    generate_ms = (time.perf_counter() - t0) * 1000

    # For local HuggingFace models, token costs are not tracked in the same way.
    # Set input_tokens and output_tokens to 0 or estimate if needed.
    return FullCtxResult(
        answer=generated_text, # Extract only the generated part
        generate_ms=generate_ms,
        input_tokens=0,  # Token tracking not applicable for local models here
        output_tokens=0, # Token tracking not applicable for local models here
    )


