"""Looking at the **"RAG Pipeline Latency Waterfall" **plot and the stage averages from cell , we can see that the Generate stage is indeed the most time-consuming and shows some variance across queries. This is common for LLMs, even smaller local ones like distilgpt2, due to several factors:

**Output Length Variability:** Although we set max_new_tokens, the actual number of tokens generated for each answer can vary. Longer answers will naturally take more time to produce.

**Input Context Complexity:** Even if the retrieved context is similar in length, the semantic complexity of the question and the context can influence the model's internal processing time for each token generated.

**Model Operations:** The generation process involves iterative token prediction. Some tokens might be easier/faster for the model to predict than others, leading to slight variations in computation per step.
Local Resource Contention: Since this model is running locally (or on a shared GPU/CPU within Colab), background processes or other demands on computational resources can introduce minor fluctuations in latency.

In our A/B evaluation, the generate stage accounts for about 73.2% of the total RAG pipeline latency (953.4ms out of 1301.6ms on average), making it the dominant factor. This variability is expected, especially with a causal language model like distilgpt2 completing a prompt.

**Extension A - Streaming Responses with Claude**

Stream tokens back in real time using the Anthropic client directly. Measure time-to-first-token (perceived responsiveness) vs total latency.
"""

# direct_client = anthropic.Anthropic(api_key=ANTHROPIC_API_KEY) # Not needed for HuggingFace streaming simulation

def rag_stream(query: str, top_k: int = TOP_K, delay_per_char_ms: float = 20) -> None:
    """Simulate streaming of HuggingFace response token-by-token (char-by-char)."""
    # Retrieve
    raw     = azure_hybrid_search(query, top_k=top_k)
    context = "\n\n".join([f"[{r['title']}]\n{r['content']}" for r in raw])
    sources = [r["title"] for r in raw]

    print(f"Query: {query}")
    print(f"Sources: {sources}")
    print("\nAnswer (simulated streaming): ", end="", flush=True)

    # Stage 3: Generate (HuggingFace) - get full response first
    formatted_prompt = (
        "Answer ONLY from the provided context. If unsure, say so. Be concise.\n\n"
        f"Context:\n{context}\n\n"
        f"Question: {query}\n"
        "Answer:"
    )

    # The HuggingFacePipeline generates the full text at once.
    # We extract the generated part and then simulate character-by-character output.
    t_start_full_gen = time.perf_counter()
    full_response = llm.invoke(formatted_prompt)
    generated_text = full_response[len(formatted_prompt):].strip()
    t_end_full_gen = time.perf_counter()

    t_start_display  = time.perf_counter()
    first_token_ms   = None

    # Simulate character-by-character streaming
    for i, char in enumerate(generated_text):
        if i == 0:
            first_token_ms = (time.perf_counter() - t_start_display) * 1000
        print(char, end="", flush=True)
        time.sleep(delay_per_char_ms / 1000) # Convert ms to seconds

    total_display_ms = (time.perf_counter() - t_start_display) * 1000
    total_actual_gen_ms = (t_end_full_gen - t_start_full_gen) * 1000

    print(f"\n\nSimulated Time to first char: {first_token_ms:.0f}ms |")
    print(f"Total simulated display time: {total_display_ms:.0f}ms |")
    print(f"Actual LLM generation time (full response): {total_actual_gen_ms:.0f}ms\n")

# Demo -- simulates streaming to the cell output in real time
rag_stream("What is the attention mechanism in transformer models?")

"""**Extension B - Confidence Score Filter**

Block answers where no retrieved chunk is relevant enough. We gate on FAISS L2 distance from similarity_search_with_score. Lower L2 distance = more similar. Tune L2_THRESHOLD to calibrate.
"""

# FAISS similarity_search_with_score returns (Document, l2_distance) tuples
# l2_distance is a float32; lower = more similar to the query
# Tune this threshold by inspecting the distribution below
L2_THRESHOLD = 1.0   # reject if best chunk L2 distance > this value

def rag_with_confidence(query: str) -> dict:
    """RAG pipeline that refuses to answer when no chunk is close enough."""
    results_with_scores = faiss_store.similarity_search_with_score(query, k=TOP_K)

    if not results_with_scores:
        return {"answer": "No results found.", "l2_distance": None, "passed": False}

    # scores are numpy float32 -- convert to plain Python float
    best_l2 = float(results_with_scores[0][1])

    if best_l2 > L2_THRESHOLD:
        return {
            "answer": (
                f"I cannot answer this confidently "
                f"(best chunk L2 distance = {best_l2:.3f} > threshold {L2_THRESHOLD}). "
                "Please ask a question related to the topics in the knowledge base."
            ),
            "l2_distance": best_l2,
            "passed": False,
        }

    # Passed threshold -- generate answer
    docs    = [doc for doc, _ in results_with_scores]
    context = "\n\n".join([f"[{d.metadata['title']}]\n{d.page_content}" for d in docs])

    # Format messages into a single prompt string for the HuggingFace model
    formatted_prompt = (
        "Answer ONLY from the provided context. If unsure, say so. Be concise.\n\n"
        f"Context:\n{context}\n\n"
        f"Question: {query}\n"
        "Answer:"
    )

    response = llm.invoke(formatted_prompt)
    # The response from a causal LM with text-generation task will include the prompt itself.
    # We extract the part of the response that comes *after* the formatted prompt.
    generated_text = response[len(formatted_prompt):].strip()

    return {"answer": generated_text, "l2_distance": best_l2, "passed": True}


# Test with in-corpus and out-of-corpus queries
test_queries = [
    ("What is the attention mechanism in transformers?",   "In-corpus -- should PASS"),
    ("How does CRISPR cut DNA?",                           "In-corpus -- should PASS"),
    ("What is the boiling point of tungsten carbide?",     "Out-of-corpus -- should BLOCK"),
    ("Recommend a good restaurant in Tokyo",               "Out-of-corpus -- should BLOCK"),
]

print(f"Confidence filter (L2 threshold = {L2_THRESHOLD})\n")
for query, label in test_queries:
    result = rag_with_confidence(query)
    status = "PASSED" if result["passed"] else "BLOCKED"
    l2_str = f"{result['l2_distance']:.3f}" if result["l2_distance"] is not None else "N/A"
    print(f"[{status}] {label}")
    print(f"  Q: {query}")
    print(f"  L2={l2_str}  A: {result['answer'][:130]}...\n")

